# Component -> version constant in internal/components/versions.go -> code paths it owns.
# Read by check-component-versions.sh and component-changelog.sh. The Web UI is not here:
# it ships with Miabi and carries Miabi's own version.
gitops           GitOpsVersion          internal/services/gitops internal/declarative
pipeline         PipelineVersion        internal/services/pipeline internal/runners
marketplace      MarketplaceVersion     internal/services/marketplace
registry         RegistryVersion        internal/services/registryserver
storage-classes  StorageClassesVersion  internal/services/storageclass internal/handlers/admin_storage_class_handler.go
analytics        AnalyticsVersion       internal/services/analytics internal/worker/analytics.go internal/handlers/analytics_handler.go
healthprobe      HealthProbeVersion     cmd/healthprobe internal/healthprobe
sealed-secrets   SealedSecretsVersion   pkg/sealed internal/services/sealing internal/services/workspacekeys internal/handlers/workspace_keys_handler.go
